/**
 * Configuration type for break variables
 */
export type BreakVariableType = {
    /** Order in which the variable appears */
    order?: number;
    /** Indicates whether the variable is active */
    active?: boolean;
    /** Disable automatic slot fill based on user context */
    disableInitialSlotFill?: boolean;
};
/**
 * A Variable for a break field (used for adding line breaks in forms).
 *
 * @see https://docs.servicenow.com/csh?topicname=variable-types.html&version=latest
 *
 * @param config - Configuration for the break variable including:
 *   * **order**? - Order in which the variable appears
 *   * **active**? - Indicates whether the variable is active
 *   * **disableInitialSlotFill**? - Disable automatic slot fill based on user context
 */
export declare function BreakVariable(config: BreakVariableType): BreakVariableType;
